-- IPA 2022-01-23 individually reviewed adaptations and repeats.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20220123-q01','exam-fe','ビット列','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問1・改編】0以上65536未満の整数xを16ビットで表し、上位8ビットと下位8ビットを入れ替える。商の整数部分を÷、余りを%で表すと、入替後の値はどれか。','[{"id":"a","text":"(x÷256)＋(x%256)"},{"id":"b","text":"(x÷256)＋(x%256)×256"},{"id":"c","text":"(x÷256)×256＋(x%256)"},{"id":"d","text":"(x÷256)×256＋(x%256)×256"}]','"b"','元の下位8ビットが上位になり256倍、上位8ビットは下位になる。中文：交换高低字节后，原低字节乘256加原高字节。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q02','exam-fe','マルコフ連鎖','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問2・改編】天気の翌日への遷移確率は、雨から雨0.2・晴れ0.3・曇り0.5、晴れから晴れ0.4、曇りから晴れ0.3である。今日が雨のとき2日後が晴れとなる確率はどれか。','[{"id":"a","text":"0.15"},{"id":"b","text":"0.27"},{"id":"c","text":"0.30"},{"id":"d","text":"0.33"}]','"d"','雨→雨→晴れ、雨→晴れ→晴れ、雨→曇り→晴れを足す。0.2×0.3＋0.3×0.4＋0.5×0.3＝0.33。中文：将三条路径概率相加，得到0.33。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q03','exam-fe','相関係数','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問3・改編】相関係数に関する適切な記述はどれか。','[{"id":"a","text":"全ての標本点が正の傾きの直線上にあれば相関係数は＋1"},{"id":"b","text":"変量間の関係が線形なら相関係数は0"},{"id":"c","text":"変量間の関係が非線形なら相関係数は負"},{"id":"d","text":"無相関のとき相関係数は−1"}]','"a"','全ての点が正の傾きの直線上にあれば完全な正の線形相関となる。中文：全部点位于正斜率直线上时，相关系数为＋1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q04','exam-fe','待ち行列','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問4・改編】複数クライアントが1台のプリンタを利用する。M/M/1待ち行列モデルの条件に反しない運用はどれか。','[{"id":"a","text":"プリンタの空き具合を見ながら印刷要求する"},{"id":"b","text":"印刷の緊急性や量にかかわらず先着順に印刷する"},{"id":"c","text":"バッファが満杯なら一時的に受付を中断する"},{"id":"d","text":"印刷時間は一定の準備時間と印刷量に比例する時間の合計である"}]','"b"','基本的なM/M/1モデルでは単一窓口で先着順を仮定する。中文：标准M/M/1模型采用单服务台、先来先服务等假设。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q06','exam-fe','PCMサンプリング','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問6・改編】音声をPCMで1標本8ビットに変換し圧縮せずリアルタイム転送すると64000ビット/秒だった。サンプリング間隔は何マイクロ秒か。','[{"id":"a","text":"15.6"},{"id":"b","text":"46.8"},{"id":"c","text":"125"},{"id":"d","text":"128"}]','"c"','64000÷8＝毎秒8000標本。1/8000秒＝125μs。中文：每秒8000次采样，间隔125微秒。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q07','exam-fe','連結リスト','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問7・改編】配列boxの1〜9にA〜Iが入り、next[0]=1、next[1]=5、next[5]=3、next[3]=7、next[7]=2、next[2]=0である。各nextは次要素の添字、0は末尾を示す。3番目と4番目の間にH（添字8）を挿入するときnext[8]はどれか。','[{"id":"a","text":"3"},{"id":"b","text":"5"},{"id":"c","text":"7"},{"id":"d","text":"8"}]','"c"','元の順序は1→5→3→7→2。3番目の後に8を入れるのでnext[8]=7。中文：原链表前三项为1、5、3，新元素8应指向原第四项7。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q08','exam-fe','ハッシュの衝突','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問8・改編】A=1、B=2、…、Z=26として3文字キーの順位合計を27で割った余りをハッシュ値とする。SEPと衝突するキーはどれか。','[{"id":"a","text":"APR"},{"id":"b","text":"FEB"},{"id":"c","text":"JAN"},{"id":"d","text":"NOV"}]','"b"','SEPは19＋5＋16＝40、余り13。FEBは6＋5＋2＝13で同じ。中文：SEP的字符序号和40除27余13，FEB的和也是13。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q09','exam-fe','再帰','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問9・改編】手続proc(n)はn=0なら戻る。それ以外ならnを出力し、proc(n−1)を呼び、再びnを出力する。proc(5)の出力はどれか。','[{"id":"a","text":"543212345"},{"id":"b","text":"5432112345"},{"id":"c","text":"54321012345"},{"id":"d","text":"543210012345"}]','"b"','呼出し時に5〜1、復帰時に1〜5を出力する。0は出力しない。中文：递归下降输出54321，返回时输出12345。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q11','exam-fe','プログラムカウンタ','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問11・改編】CPUのプログラムレジスタ（プログラムカウンタ）の役割はどれか。','[{"id":"a","text":"演算のためメモリから読み出したデータを保持する"},{"id":"b","text":"条件分岐のため演算結果の状態を保持する"},{"id":"c","text":"デコードのため読み出した命令を保持する"},{"id":"d","text":"次に読み出す命令の格納アドレスを保持する"}]','"d"','プログラムカウンタは次に実行する命令のアドレスを示す。中文：程序计数器保存下一条指令的地址。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q12','exam-fe','コンピュータの五大装置','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問12・改編】命令はコンピュータの五大装置のうちどの装置から取り出され、どの装置で解釈されるか。','[{"id":"a","text":"演算装置から取出し、制御装置で解釈"},{"id":"b","text":"記憶装置から取出し、制御装置で解釈"},{"id":"c","text":"制御装置から取出し、演算装置で解釈"},{"id":"d","text":"入力装置から取出し、演算装置で解釈"}]','"b"','プログラムは記憶装置に格納され、制御装置が命令を解読する。中文：指令从存储器取出，由控制器译码。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q14','exam-fe','デイジーチェーン','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問14・改編】デイジーチェーン接続の例はどれか。','[{"id":"a","text":"PCに計測器とプリンタをそれぞれ別のポートで接続"},{"id":"b","text":"PCからディスプレイ1台目に接続し、その1台目から2台目へ接続"},{"id":"c","text":"キーボードやマウスをUSBハブにつなぎハブをPCに接続"},{"id":"d","text":"カメラとPCをネットワークハブに接続"}]','"b"','機器を数珠つなぎに直列接続する方式。中文：菊花链接将设备依次串接。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q15','exam-fe','フォールトトレランス','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問15・改編】フォールトトレラントシステムの実現方法として最も適切なものはどれか。','[{"id":"a","text":"複数台のコンピュータで多重化する"},{"id":"b","text":"フェールソフトでなくフェールセーフ構造にする"},{"id":"c","text":"多重化せず重要処理を高稼働率の装置だけで処理する"},{"id":"d","text":"ハードウェアではなくソフトウェアだけで実現する"}]','"a"','冗長化により一部の故障時も処理を継続しやすくする。中文：通过多机冗余提高发生故障时的持续运行能力。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q16','exam-fe','信頼性','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問16・改編】コンピュータシステムの信頼性に関する記述で適切なものはどれか。','[{"id":"a","text":"MTBF/(MTBF＋MTTR)はシステムの稼働時間の割合を表す"},{"id":"b","text":"MTBF−MTTRはシステムが正常だった時間を表す"},{"id":"c","text":"MTBFは運用開始から最初の故障までの時間を表す"},{"id":"d","text":"MTTRは復旧から次の故障までの平均時間を表す"}]','"a"','稼働率は平均故障間隔を平均故障間隔と平均修復時間の和で割る。中文：可用率＝平均故障间隔÷（平均故障间隔＋平均修复时间）。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q17','exam-fe','スプーリング','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問17・改編】4つのジョブはCPU多重度1で各20分処理し、完了時に400MBをスプールする。プリンタ1台は100MBを10分で印刷し、CPUと並行して動作する。最初のCPU処理開始から最後の印刷終了まで何分か。','[{"id":"a","text":"120"},{"id":"b","text":"160"},{"id":"c","text":"180"},{"id":"d","text":"240"}]','"c"','最初の印刷は20分後に開始し、40分ずつ4件を連続印刷するので20＋160＝180分。中文：20分钟后开始首份打印，四份各40分钟，共180分钟。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q18','exam-fe','プリンタ割当て','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問18・改編】空いている3台のプリンタA、B、Cに待ち行列の要求を順に割り当てる。割当てはAから順に空きを探し、Cの次はAに戻る。印刷時間が5、12、4、3、10、4分のとき、各プリンタの最後の印刷終了時刻が遅い順はどれか。','[{"id":"a","text":"A,B,C"},{"id":"b","text":"B,A,C"},{"id":"c","text":"B,C,A"},{"id":"d","text":"C,B,A"}]','"a"','最初はA5、B12、C4。Cが3分、Aが10分、Cが4分を追加し、終了時刻はA15、B12、C11分。中文：模拟分配得到最后完成时间A15、B12、C11分钟。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q19','exam-fe','ページフォールト','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問19・改編】ページング方式で空きページのない主記憶に存在しないページを参照した。処理順として適切なものはどれか。','[{"id":"a","text":"置換対象決定→ページイン→ページフォールト→ページアウト"},{"id":"b","text":"置換対象決定→ページフォールト→ページアウト→ページイン"},{"id":"c","text":"ページフォールト→置換対象決定→ページアウト→ページイン"},{"id":"d","text":"ページフォールト→置換対象決定→ページイン→ページアウト"}]','"c"','ページフォールト後に置換ページを決定し、必要なら退避してから要求ページを読み込む。中文：缺页后选择替换页，必要时换出，再换入所需页面。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q20','exam-fe','PWM','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問20・改編】モータ速度制御などに用いるPWMの、フィルタ通過前の駆動波形の特徴はどれか。','[{"id":"a","text":"パルス幅は同じで電圧の高さが変わる"},{"id":"b","text":"電圧の高さは一定でパルスの幅が変わる"},{"id":"c","text":"階段状に電圧が変化する"},{"id":"d","text":"3種類の電圧が周期的に入れ替わる"}]','"b"','PWMはパルスのオン時間やデューティ比を変化させて制御する。中文：脉宽调制保持脉冲电平，通过改变脉宽控制平均输出。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q21','exam-fe','NAND回路','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問21・改編】AとBのNANDをXとし、Y＝NAND(NAND(A,X),NAND(B,X))とする。Yと等価な回路はどれか。','[{"id":"a","text":"OR"},{"id":"b","text":"AND"},{"id":"c","text":"XOR"},{"id":"d","text":"NOR"}]','"c"','4個のNANDで構成したXOR回路。入力が異なる場合だけ1となる。中文：四个与非门组成异或门，两输入不同时输出1。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q24','exam-fe','動画の帯域幅','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問24・改編】800×600ピクセル、24ビットカラー、30フレーム/秒の動画を圧縮せず配信する。最低限必要な帯域幅は約幾らか。','[{"id":"a","text":"350kビット/秒"},{"id":"b","text":"3.5Mビット/秒"},{"id":"c","text":"35Mビット/秒"},{"id":"d","text":"350Mビット/秒"}]','"d"','800×600×24×30＝345600000ビット/秒で約350Mビット/秒。中文：像素数乘24位和每秒30帧，约350Mbps。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q25','exam-fe','正規化','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問25・改編】注文記録に注文番号、注文日、顧客番号、顧客名、商品番号、商品名、数量、販売単価がある。注文番号→注文日・顧客番号、顧客番号→顧客名、商品番号→商品名、(注文番号,商品番号)→数量・販売単価。第3正規形に分解した注文明細はどれか。','[{"id":"a","text":"主キー(注文番号,顧客番号,商品番号)、顧客名、数量、販売単価"},{"id":"b","text":"主キー(注文番号,顧客番号)、数量、販売単価"},{"id":"c","text":"主キー(注文番号,商品番号)、数量、販売単価"},{"id":"d","text":"主キー(注文番号)、数量、販売単価"}]','"c"','明細を識別する複合キーは注文番号と商品番号で、数量と販売単価がそれに従属する。中文：订单明细以订单号和商品号为组合主键，保存数量和销售单价。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q26','exam-fe','SQLカーソル','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問26・改編】埋込みSQLで問合せ結果を1行ずつ親プログラムへ渡す操作に関係する字句はどれか。','[{"id":"a","text":"CURSOR"},{"id":"b","text":"ORDER BY"},{"id":"c","text":"UNION"},{"id":"d","text":"UNIQUE"}]','"a"','カーソルを使って結果集合から行を順に取得する。中文：游标用于逐行读取查询结果。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q29','exam-fe','排他制御','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問29・改編】複数のトランザクションが同一データベースを同時更新するとき、論理的矛盾を防ぐために用いる技法はどれか。','[{"id":"a","text":"再編成"},{"id":"b","text":"正規化"},{"id":"c","text":"整合性制約"},{"id":"d","text":"排他制御"}]','"d"','排他制御は同時更新が競合しないようアクセスを制御する。中文：并发控制通过锁等机制避免同时更新产生矛盾。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q30','exam-fe','SSID','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問30・改編】無線LANのSSIDの説明として適切なものはどれか。','[{"id":"a","text":"48ビットのネットワーク識別子でアクセスポイントのMACアドレスと一致する"},{"id":"b","text":"48ビットのホスト識別子で有線LANのMACアドレスと同様に働く"},{"id":"c","text":"最大32オクテットのネットワーク識別子で接続先アクセスポイントの選択に用いる"},{"id":"d","text":"最大32オクテットのホスト識別子でネットワーク上で一意である"}]','"c"','SSIDは無線LANのネットワーク名であり、接続先の識別に用いる。中文：SSID是无线网络标识，最长32字节，并非主机唯一标识。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q32','exam-fe','サブネット','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問32・改編】サブネットマスクが255.255.255.240のとき、同一サブネットに属するIPv4アドレスの組合せはどれか。','[{"id":"a","text":"192.168.1.14と192.168.1.17"},{"id":"b","text":"192.168.1.17と192.168.1.29"},{"id":"c","text":"192.168.1.29と192.168.1.33"},{"id":"d","text":"192.168.1.33と192.168.1.49"}]','"b"','/28では下位の範囲は16刻み。17と29はいずれも16〜31に属する。中文：/28每个子网16个地址，17与29同属16至31区间。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q36','exam-fe','RSA','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問36・改編】素因数分解の困難性を利用した公開鍵暗号方式はどれか。','[{"id":"a","text":"AES"},{"id":"b","text":"DH"},{"id":"c","text":"DSA"},{"id":"d","text":"RSA"}]','"d"','RSAの安全性は大きな整数の素因数分解などの困難性に基づく。中文：RSA利用大整数分解等数学难题构建公钥密码。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q40','exam-fe','公開鍵暗号','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問40・改編】AがBだけに秘密の文章を送るため公開鍵暗号を使い、Bが自分の秘密鍵で復号する。Aが暗号化に用いる鍵はどれか。','[{"id":"a","text":"Aの公開鍵"},{"id":"b","text":"Aの秘密鍵"},{"id":"c","text":"Bの公開鍵"},{"id":"d","text":"共通鍵"}]','"c"','受信者Bの公開鍵で暗号化すると対応するBの秘密鍵で復号できる。中文：保密传输用收件人的公钥加密，由收件人的私钥解密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q41','exam-fe','ディジタル署名','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問41・改編】Aが注文に自分の秘密鍵でディジタル署名し、BがAの公開鍵で署名を検証する。実現できることはどれか。','[{"id":"a","text":"注文内容が第三者に漏れないようにする"},{"id":"b","text":"注文が必ずBに届くようにする"},{"id":"c","text":"BからAへの商品販売が許可されていることを確認する"},{"id":"d","text":"Bに届いた注文がAの秘密鍵で署名されたことを確認する"}]','"d"','署名検証は署名者の鍵との対応とデータの完全性を確認する。中文：验证签名可确认订单对应A的私钥，并检查内容是否被修改。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q43','exam-fe','デジタルフォレンジックス','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問43・改編】デジタルフォレンジックスの説明はどれか。','[{"id":"a","text":"設定した基準でメールをフィルタリングする"},{"id":"b","text":"外部攻撃からサーバを防御する"},{"id":"c","text":"廃棄前の記憶媒体にデータを上書きする"},{"id":"d","text":"不正アクセスなどの調査で法的証拠性に配慮しデータを保全・収集・分析する"}]','"d"','原因究明に必要なデータを証拠性に配慮して扱う。中文：数字取证在保护证据完整性和可用性的前提下保存、收集并分析数据。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q44','exam-fe','磁気ディスク廃棄','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問44・改編】機密ファイルを含む正常動作するPCの磁気ディスクを廃棄業者に渡す前の情報漏えい対策として適切なものはどれか。','[{"id":"a","text":"異なる方式でファイルを複数回圧縮する"},{"id":"b","text":"マスタブートレコードだけを複数回消去する"},{"id":"c","text":"ランダムなビット列で磁気ディスク全領域を複数回上書きする"},{"id":"d","text":"ファイル名をランダムな文字列に変更する"}]','"c"','磁気ディスクの全領域を消去することでファイル内容の復元を困難にする。中文：对磁盘全区域执行可靠的数据清除，单纯改名或压缩无法删除内容。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q45','exam-fe','要求分析インタビュー','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問45・改編】システムの要求分析におけるインタビューの留意点として適切なものはどれか。','[{"id":"a","text":"回答が事実か推測かを区別する"},{"id":"b","text":"対象者を業務の直接担当者だけに限定する"},{"id":"c","text":"質問内容を事前に渡すことを避ける"},{"id":"d","text":"質問をはい・いいえで答えられるものだけに限定する"}]','"a"','得られた情報の事実と推測を区別し、必要に応じて確認する。中文：应区分受访者陈述的是事实还是推测。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q46','exam-fe','モジュール強度','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問46・改編】上位から渡された処理コードI、U、Dによって、それぞれ挿入、更新、削除のいずれかを選んで処理するモジュールの評価はどれか。','[{"id":"a","text":"暗合的強度であり機能間に特別な関係がない"},{"id":"b","text":"情報的強度であり各処理に入口点があって制御の結びつきがない"},{"id":"c","text":"連絡的強度であり複数機能をデータ受渡しで逐次実行する"},{"id":"d","text":"論理的強度であり関連機能からパラメタで一つを選ぶ"}]','"d"','処理コードで複数の関連処理から選択する形は論理的強度。機能ごとの分割などを検討する。中文：由参数选择执行哪一种相关功能，属于逻辑内聚。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q47','exam-fe','分岐・条件網羅','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問47・改編】判定1は「x≧1 OR y＝1」、判定2は「y＞1」。両判定の真偽と、判定1を構成する各条件の真偽を全て通すテストデータはどれか。各組は(x,y)。','[{"id":"a","text":"(2,2),(1,2)"},{"id":"b","text":"(1,2),(0,0)"},{"id":"c","text":"(1,2),(1,1),(0,1)"},{"id":"d","text":"(1,2),(0,1),(0,2)"}]','"d"','(1,2)で判定1真・判定2真、(0,1)で判定1真・判定2偽、(0,2)で判定1偽。両原子条件の真偽も現れる。中文：三组覆盖两个判断的真假，以及OR内各条件的真假。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q48','exam-fe','テストスタブ','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問48・改編】結合テストで使うスタブの役割はどれか。','[{"id":"a","text":"テストが完了したモジュールの代わりに結合される"},{"id":"b","text":"テスト対象からの呼出し条件に応じて値を返す"},{"id":"c","text":"呼出し条件に合わせてテストデータを自動生成する"},{"id":"d","text":"テスト対象のモジュールを呼び出す"}]','"b"','スタブはテスト対象が呼び出す下位モジュールの代役。中文：桩模拟被测试模块调用的下层模块并返回结果。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q50','exam-fe','レトロスペクティブ','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問50・改編】アジャイル開発でふりかえり（レトロスペクティブ）を行う適切なタイミングはどれか。','[{"id":"a","text":"タスクボードのカードが移動されたとき"},{"id":"b","text":"各イテレーションの最後"},{"id":"c","text":"毎日行う朝会"},{"id":"d","text":"毎日全員がニコニコカレンダーに記入し終えたとき"}]','"b"','イテレーションの終わりにチームで進め方を振り返り改善を考える。中文：每次迭代结束时回顾协作过程并制定改进。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q51','exam-fe','EVM','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問51・改編】プロジェクトのパフォーマンス測定に用いるEVMの管理対象の組合せはどれか。','[{"id":"a","text":"コストとスケジュール"},{"id":"b","text":"コストとリスク"},{"id":"c","text":"スケジュールと品質"},{"id":"d","text":"品質とリスク"}]','"a"','EVMは出来高を基準としてコストとスケジュールの実績・計画を比較する。中文：挣值管理结合进度和成本衡量项目绩效。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q52','exam-fe','ガントチャート','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問52・改編】工程管理で使うガントチャートの特徴はどれか。','[{"id":"a","text":"工程管理上の重要ポイントに着目する"},{"id":"b","text":"各作業の順序関係、所要日数、余裕日数を把握する"},{"id":"c","text":"作業開始と終了の予定・実績や仕掛かり中の作業を把握する"},{"id":"d","text":"出来高の時間的推移を表し費用と進捗を同時管理する"}]','"c"','ガントチャートは時間軸に各作業の予定・実績を表示する。中文：甘特图显示工作计划、实际起止和进行情况。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q53','exam-fe','クリティカルパス','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問53・改編】開始点からA=1日とB=5日に分岐。A後にC=3日とD=3日が開始し、BとC完了後にE=4日が開始。E後にF=5日、DとE完了後にG=4日が開始し、FとGの完了で終了する。クリティカルパスはどれか。','[{"id":"a","text":"A,C,E,F"},{"id":"b","text":"A,D,G"},{"id":"c","text":"B,E,F"},{"id":"d","text":"B,E,G"}]','"c"','候補経路は順に13、8、14、13日。最長はB→E→Fの14日。中文：各路径耗时分别13、8、14、13天，关键路径为B-E-F。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q55','exam-fe','SLA','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問55・改編】SLAの説明はどれか。','[{"id":"a","text":"ITサービス管理のベストプラクティスを集めたフレームワーク"},{"id":"b","text":"開発から保守までのソフトウェアライフサイクルプロセス"},{"id":"c","text":"サービスと目標値に関する提供者と顧客の合意"},{"id":"d","text":"品質マネジメントシステムの国際規格"}]','"c"','SLAはサービス内容や可用性などの水準を提供者と利用者が合意するもの。中文：服务等级协议约定服务内容及目标水平。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q56','exam-fe','ミッションクリティカル','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問56・改編】ミッションクリティカルシステムとはどれか。','[{"id":"a","text":"OSのように業務システムの稼働に必要なシステム"},{"id":"b","text":"性能の限界に近い状態で稼働するシステム"},{"id":"c","text":"障害時に企業活動や社会へ重大な影響を及ぼすシステム"},{"id":"d","text":"先行試験後に本格導入されるシステム"}]','"c"','障害や停止が事業・社会に重大な影響をもたらす重要システムを指す。中文：任务关键系统发生故障会对业务或社会造成重大影响。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q57','exam-fe','コールドスタート','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問57・改編】障害後、システムを初期状態に戻し、更新前後コピーの前処理を伴わず再開する方法はどれか。','[{"id":"a","text":"ウォームスタート"},{"id":"b","text":"コールドスタート"},{"id":"c","text":"ロールバック"},{"id":"d","text":"ロールフォワード"}]','"b"','コールドスタートは初期状態からの再起動で、初期プログラムロードとも呼ばれる。中文：冷启动将系统恢复至初始状态再启动。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q59','exam-fe','監査可能性','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問59・改編】情報システムの監査可能性を説明したものはどれか。','[{"id":"a","text":"コントロールの有効性を監査できるようシステムが設計・運用されていること"},{"id":"b","text":"監査人が監査の目的に合致する手続を行う能力を持つこと"},{"id":"c","text":"入手した証拠の十分性と報告書の完成度が保たれていること"},{"id":"d","text":"情報システム部門の積極的な協力が得られること"}]','"a"','監査可能性はログや証跡などによって統制を検証できるシステムの性質。中文：可审计性是系统被设计和运行得能够检查控制措施的有效性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q60','exam-fe','コントロールトータルチェック','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問60・改編】システム間のデータ連携で、送信件数の合計と受信件数の合計を照合するコントロールはどれか。','[{"id":"a","text":"アクセスコントロール"},{"id":"b","text":"エディットバリデーションチェック"},{"id":"c","text":"コントロールトータルチェック"},{"id":"d","text":"チェックデジット"}]','"c"','件数や金額などの合計を処理前後で照合し欠落などを検出する。中文：控制总计检查通过比较发送和接收总数发现遗漏。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q63','exam-fe','データサイエンス力','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問63・改編】データサイエンス力をAI・統計などで予測、検定、関係把握、データ加工・可視化する力と定義する。該当するスキルはどれか。','[{"id":"a","text":"データ規模と機密性を踏まえオンプレミスかクラウドを選びシステムを設計する"},{"id":"b","text":"事業モデルやバリューチェーンを理解し問題の大枠を整理する"},{"id":"c","text":"分散処理フレームワークで並列処理システムを設計する"},{"id":"d","text":"分析要件に応じて決定木やニューラルネットワークの手法を選び、パラメータ設定と結果評価を行う"}]','"d"','分析手法の選択、モデル設定、評価はデータサイエンス力に該当する。中文：选择建模方法、调参和评价分析结果属于数据科学能力。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q64','exam-fe','非機能要件','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問64・改編】受注管理システムの要件のうち非機能要件はどれか。','[{"id":"a","text":"注文時に与信残額を計算しマイナスなら警告を表示する"},{"id":"b","text":"定められた稼働率を維持するため障害発生時は半日以内に回復する"},{"id":"c","text":"在庫切れ商品を担当者に警告する"},{"id":"d","text":"受注承認された注文のみ出荷する"}]','"b"','障害からの回復時間は可用性・信頼性に関する非機能要件。中文：故障恢复时间属于可用性方面的非功能需求。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q65','exam-fe','RFP','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問65・改編】提案依頼書RFPの作成と提案依頼に当たって取得者側の対応として適切なものはどれか。','[{"id":"a","text":"要求事項を最小限にし曖昧な点を都度確認させる"},{"id":"b","text":"実現性調査を全てベンダに任せる"},{"id":"c","text":"複数の要求事項について重要度をあらかじめ設定する"},{"id":"d","text":"機能ではなく特定製品名や実現手段を細かく指定する"}]','"c"','要求の優先度を示し、提案の比較と調整をしやすくする。中文：在RFP中标明需求优先级，便于供应商提出方案和评估。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q66','exam-fe','バリューチェーン分析','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問66・改編】企業活動を主活動と支援活動に分け、顧客に提供する価値がどの活動で生み出されるかを分析する手法はどれか。','[{"id":"a","text":"3C分析"},{"id":"b","text":"SWOT分析"},{"id":"c","text":"バリューチェーン分析"},{"id":"d","text":"ファイブフォース分析"}]','"c"','企業活動を価値の連鎖として捉え、価値や競争優位の源泉を分析する。中文：价值链分析将活动分为主要与支持活动，分析价值来源。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q67','exam-fe','デルファイ法','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問67・改編】専門家にアンケートを実施し、結果を互いに参照して調査を繰り返し意見を収束させる予測手法はどれか。','[{"id":"a","text":"因果関係分析法"},{"id":"b","text":"クロスセクション法"},{"id":"c","text":"時系列回帰分析法"},{"id":"d","text":"デルファイ法"}]','"d"','専門家への反復調査とフィードバックで意見を集約する。中文：德尔菲法通过多轮专家调查及反馈汇聚意见。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q68','exam-fe','バランススコアカード','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問68・改編】バランススコアカードの説明はどれか。','[{"id":"a","text":"外部環境と内部環境から事業機会を導き出す"},{"id":"b","text":"計画、行動、評価、修正のサイクルで管理する"},{"id":"c","text":"財務、顧客、内部ビジネスプロセス、学習と成長の四つの視点から戦略の立案と実行を支援する"},{"id":"d","text":"業務プロセスをモニタリングする単一の指標"}]','"c"','四つの視点を用いて戦略と目標・指標を結び付ける。中文：平衡计分卡从四个视角支持战略制定与执行。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q69','exam-fe','パテントプール','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問69・改編】MPEG-4などに存在するパテントプールの説明はどれか。','[{"id":"a","text":"市場の実勢により事実上標準となった規格"},{"id":"b","text":"著作権表示を保持して使用・改変・再配布を認める仕組み"},{"id":"c","text":"特許料が無償でライセンスされた技術"},{"id":"d","text":"複数企業が特許権を持ち寄り一括して管理する仕組み"}]','"d"','複数の権利者が関連特許をまとめて管理し、利用許諾を行う仕組み。中文：专利池汇集多个权利人的相关专利并统一管理授权。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q70','exam-fe','HEMS','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問70・改編】IoTの応用事例でHEMSを説明したものはどれか。','[{"id":"a","text":"工場機械のセンサ情報で劣化を分析し部品を交換する"},{"id":"b","text":"車載センサ情報を分析して運転を支援する"},{"id":"c","text":"公共設備や交通システムのエネルギーを最適制御する"},{"id":"d","text":"家庭内のエネルギー機器や家電をネットワークに接続し消費を可視化・最適制御する"}]','"d"','HEMSは家庭内のエネルギー管理システム。中文：家庭能源管理系统连接家电和能源设备，监测并优化消耗。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q72','exam-fe','電子自治体','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問72・改編】電子自治体におけるG to Bの例はどれか。','[{"id":"a","text":"自治体内の電子決裁と電子公文書管理"},{"id":"b","text":"自治体が使用する物品や資材の電子調達・電子入札"},{"id":"c","text":"自治体間で住民票データを送受信する"},{"id":"d","text":"住民票や戸籍謄本などを電子申請する"}]','"b"','G to Bは行政と企業の間の電子的取引やサービス。中文：G to B是政府与企业之间的电子业务，如电子采购。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q75','exam-fe','ABC分析','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問75・改編】不良品数は製品Pから順に182、136、120、98、91、83、70、60、35で合計875個。件数の多い順に累積し、70%以上になるまでをA群とすると何種類か。','[{"id":"a","text":"3"},{"id":"b","text":"4"},{"id":"c","text":"5"},{"id":"d","text":"6"}]','"c"','上位4種は536個で約61.3%、5種は627個で約71.7%。よって5種類。中文：前4种占61.3%，加上第5种后占71.7%，因此A组有5种。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q76','exam-fe','意思決定木','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問76・改編】施策aの初期費用30億円。確率0.4で追加費用60を払うと売上増が確率0.3で200、0.7で100、払わないと50。確率0.6では売上増120。施策bの初期費用40億円。確率0.3で追加費用40を払うと売上増が確率0.4で150、0.6で100、払わないと70。確率0.7では売上増140。追加するかは各時点で最適に選ぶ。利益増の期待値が最大の組合せはどれか。','[{"id":"a","text":"施策a、70億円"},{"id":"b","text":"施策a、160億円"},{"id":"c","text":"施策b、82億円"},{"id":"d","text":"施策b、162億円"}]','"c"','aの追加時は130−60＝70が50より有利で、全体は0.4×70＋0.6×120−30＝70。bは120−40＝80が70より有利で、0.3×80＋0.7×140−40＝82。中文：分别比较追加与不追加，a期望70亿、b期望82亿。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q77','exam-fe','線形計画法','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問77・改編】製品A,B,Cの単位当たり(製造時間,原料kg,利益千円)は(2,2,8)、(3,1,5)、(1,2,5)。月間製造時間240時間、原料150kgの上限の下で利益最大となる生産数を求める手法はどれか。','[{"id":"a","text":"移動平均法"},{"id":"b","text":"最小二乗法"},{"id":"c","text":"線形計画法"},{"id":"d","text":"定量発注法"}]','"c"','目的関数と制約を一次式で表す生産計画には線形計画法を用いる。中文：时间、原料约束和利润目标均为线性，可使用线性规划。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q79','exam-fe','著作権','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問79・改編】著作権法による保護対象はどれか。','[{"id":"a","text":"ソースプログラムそのもの"},{"id":"b","text":"データ通信のプロトコル"},{"id":"c","text":"プログラムに組み込まれたアイディア"},{"id":"d","text":"プログラムのアルゴリズム"}]','"a"','創作的なプログラムの表現は著作物となるが、アイデアやアルゴリズム自体は表現とは区別される。中文：具有创作性的程序源代码表达受到著作权保护，思想和算法本身不同。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20220123-q80','exam-fe','営業秘密','standard','single_choice','【IPA 2021年度 修了認定試験 2022-01-23 問80・改編】営業秘密の要件は秘密として管理されていること、事業に有用な情報であることと、もう一つはどれか。','[{"id":"a","text":"営業譲渡が可能であること"},{"id":"b","text":"期間が10年を超えないこと"},{"id":"c","text":"公然と知られていないこと"},{"id":"d","text":"特許出願していること"}]','"c"','営業秘密には秘密管理性、有用性、非公知性の三要件がある。中文：商业秘密须具备秘密管理性、实用性及非公开性。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20220123_FE.pdf','ja','A','explicit','standard','fe_exemption');
